from __future__ import division
from builtins import str
from builtins import range
from builtins import object
import time
import socket
from past.utils import old_div
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
import paramiko
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str
logger = BackgroundLogger.Instance()


class Rrb(object):
    def __init__(self):
        """
        Init fucntion of Rrb class
        """
        self.rrb_command = {
            'rrb': {
                'rrb_switch_off': 'gpio write {}s 0',
                'rrb_switch_on': 'gpio write {}s 1',
                'rrb_read': 'gpio read {}s',
            },
        }
        self.communicator = Communicator.get_instance()
        self.config = ConfigHandler.get_config()

    def _execute_cmd__via_paramiko(self, ip, username, password, cmd):
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        logger.info("ip {} username {} password {}".format(ip, username, password))
        ssh.connect(hostname=ip, port=22, username=username, password=password, look_for_keys=False, allow_agent=False)
        stdin, stdout, stderr = ssh.exec_command(cmd)
        output = decode_str(stdout.read())
        status = stdout.channel.recv_exit_status()
        ssh.close()
        return (output, status)

    def wait_till_port_connects(self, ip, port, timeout):
        """

        Tries to connect a remote port in for given timeout.

        Args:
            ip (str): IP address
            port (str): port number
            timeout (int): timeout in seconds

        Returns:
            bool: True if the connection successful. False if not able to connect.

        """
        # count = old_div(int(timeout), 5)
        count = old_div(int(timeout), int(5))
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(2)
        for index in range(int(count)):
            logger.info("Wait till port connect : Trying to connect {0} port on {1}".format(port, ip))
            if not sock.connect_ex((ip, int(port))):
                logger.info("Wait till port connect : Connected to {0} on {1} after {2} sec".format(ip, port,
                                                                                                    str(index * 5)))
                sock.close()
                return True
            time.sleep(5)
        else:
            logger.info("Wait till port connect : Failed to connect {0} on port {1} after {2} sec ".format(
                ip, port, str(timeout)))
            sock.close()
            return False

    def wait_till_port_disconnects(self, ip, port, timeout):
        """

        Tries to connect a remote port in for given timeout.

        Args:
            ip (str): IP address
            port (str): port number
            timeout (int): timeout in seconds

        Returns:
            bool: True if the connection successful. False if not able to connect.

        """
        count = old_div(int(timeout), int(5))
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(2)
        for index in range(count):
            logger.info("Wait till port disconnect : Trying to connect {0} port on {1}".format(port, ip))
            if sock.connect_ex((ip, int(port))):
                logger.info("Wait till port disconnect : Not Connected to {0} on {1} after {2} sec".format(
                    ip, port, str(index * 5)))
                return True
            time.sleep(2)
        else:
            logger.info("Wait till port disconnect : Can connect to {0} on port {1} after {2} sec ".format(
                ip, port, str(timeout)))
            sock.close()
            return False

    def on(self, dut, retry=False, timeout=300):
        """

        Switches on RRB Port

        Args:
            dut (str): section name to read from setup.
            retry (bool): True to retry
            timeout (int): timeout in seconds

        Returns:
            None

        Raises:
            Exception: If dut is not up

        """
        logger.info('RRB :: Switching on RRB for ' + dut)
        if 'rrb_type' in list(self.config[dut].keys()):
            self.rrb_type = self.config[dut]['rrb_type']
            self.rrb_username = self.config[dut]['rrb_username']
            self.rrb_password = self.config[dut]['rrb_password']
            if not self.rrb_type.lower() in self.rrb_command:
                raise Exception("RRB Power on failed - PowerBox of type {} is not supported".format(self.rrb_type))

        port = self.config[dut]['rrb_port']
        ip = self.config[dut]['remote_reset_ip']

        rrb_on_command = self.rrb_command[self.rrb_type].get('rrb_switch_on').format(port)
        logger.info('RRB :: RRB Switch on command ' + rrb_on_command)

        # output, status = self.communicator.execute_command_remotely_and_verify(self.config[dut]['remote_reset_ip'],
        #                                                                        self.rrb_username, self.rrb_password,
        #                                                                        rrb_on_command)
        output, status = self._execute_cmd__via_paramiko(ip, self.rrb_username, self.rrb_password, rrb_on_command)
        logger.info("RRB :: RRB Command execution :: output : {0}  status: {1}".format(output, status))
        if self.rrb_type == "rrb":
            for index in range(3):
                if not self._rrb_status_validation(dut, 1):
                    logger.warn("RRB Power status is still off.. Retrying...")
                    time.sleep(2)
                    # output, status = self.communicator.execute_command_remotely_and_verify(self.config.get(dut).get(
                    #     'remote_reset_ip'), self.rrb_username, self.rrb_password, rrb_on_command)
                    output, status = self._execute_cmd__via_paramiko(ip, self.rrb_username, self.rrb_password,
                                                                     rrb_on_command)
                    logger.info("RRB :: RRB Command execution :: output : {0}  status: {1}".format(output, status))
                else:
                    break
            else:
                raise Exception("RRB Power status is still off after 3 retries.. Faulty RRB - ip {0} port {1}".format(
                    ip, port))
        if not self.wait_till_port_connects(self.config.get(dut).get('ip'), 22, timeout):
            if not retry:
                raise Exception("RRB Power on failed for section {0}  with ip {1} timeout {2}".format(
                    dut, self.config.get(dut).get('ip'), timeout))
            logger.info("RRB Power on failed for section {0}  with ip {1} timeout {2}, but retrying is enabled".format(
                dut, self.config.get(dut).get('ip'), timeout))
            self.rrb_reset(dut)

    def _rrb_status_validation(self, dut, validate):
        """

        Read port status and validate against input

        Args:
            dut (str): section name to read from setup.
            validate: validation input

        Returns:
            bool

        """
        if self.rrb_type == "rrb":
            rrb_read_command = self.rrb_command.get(self.rrb_type).get(
                'rrb_read').format(self.config.get(dut).get('rrb_port'))
            # output, status = self._execute_cmd__via_paramiko(self.config[dut]['remote_reset_ip'], self.rrb_username,
            #                                                  self.rrb_password, rrb_read_command)
            output, status = self.communicator.execute_command_remotely_and_verify(
                self.config[dut]['remote_reset_ip'],
                self.rrb_username, self.rrb_password, rrb_read_command)
            logger.info("RRB :: RRB status {0}".format(output.strip()))
            if output.strip() != str(validate):
                return False
        return True

    def off(self, dut, timeout=120):
        """

        Switches off RRB port

        Args:
            dut (str): section name to read from setup.
            timeout (int): timeout for the operations

        Returns:
            None

        Raises:
            Exception: If dut is not going down

        """
        if 'rrb_type' in list(self.config[dut].keys()):
            self.rrb_type = self.config[dut]['rrb_type']
            self.rrb_username = self.config[dut]['rrb_username']
            self.rrb_password = self.config[dut]['rrb_password']
            if not self.rrb_type.lower() in self.rrb_command:
                raise Exception("RRB Power off failed - PowerBox of type {} is not supported".format(self.rrb_type))

        port = self.config[dut]['rrb_port']
        ip = self.config[dut]['remote_reset_ip']
        rrb_off_command = self.rrb_command.get(self.rrb_type).get('rrb_switch_off').format(port)
        logger.info('RRB :: RRB Switch off command ' + rrb_off_command)
        # output, status = self._execute_cmd__via_paramiko(ip, self.rrb_username, self.rrb_password, rrb_off_command)
        output, status = self.communicator.execute_command_remotely_and_verify(
            self.config[dut]['remote_reset_ip'],
            self.rrb_username, self.rrb_password, rrb_off_command)
        logger.info("RRB :: RRB Command execution :: output : {0}  status: {1}".format(output, status))
        if self.rrb_type == "rrb":
            for index in range(3):
                if not self._rrb_status_validation(dut, 0):
                    logger.warn("RRB Power status is still on.. Retrying...")
                    time.sleep(2)
                    # output, status = self._execute_cmd__via_paramiko(ip, self.rrb_username, self.rrb_password,
                    #                                                  rrb_off_command)
                    output, status = self.communicator.execute_command_remotely_and_verify(
                        self.config[dut]['remote_reset_ip'],
                        self.rrb_username, self.rrb_password, rrb_off_command)
                    logger.info("RRB :: RRB Command execution :: output : {0}  status: {1}".format(output, status))
                else:
                    break
            else:
                raise Exception("RRB Power status is still on after 3 retries.. Faulty RRB - ip {0} port {1}".format(
                    ip, port))
        if not self.wait_till_port_disconnects(self.config[dut]['ip'], 22, timeout):
            raise Exception("RRB Power off failed for section {0}  with ip {1} timeout {2}".format(
                dut, self.config[dut]['ip'], timeout))

    def rrb_reset(self, dut, force_reset=True, retry=False, timeout=300):
        """
        Resets the RRB port
        Args:
            dut (str): section name to read from setup.
            force_reset {bool): True if need to reset forefully
            retry (bool): True to retry
            timeout (int): timeout in seconds

        Returns:
            None

        Exceptions:
        """
        if not force_reset:
            if self.wait_till_port_connects(self.config[dut]["ip"], 22, timeout):
                logger.info("RRB :: Machine is up. Force reset is disabled, Not Resetting the board")
                return
        logger.info('RRB: Machine is not up/ force reset enabled. Resetting the board')
        self.off(dut, timeout)
        self.on(dut, retry, timeout)
